const bounded = inputs.boundedSchedule;
const critical = bounded.map((t) => ({
  id: t.id,
  duration: t.duration,
  priority: t.priority,
  ramMb: t.ramMb,
  isCritical: t.slack === 0,
  estStart: t.estStart,
  estFinish: t.estFinish,
}));
return { criticalSchedule: critical };
```

